{"description":"Extract URL patterns from climate obs readme","command":"python3 -c "
import re,html
t=open('/workspace/fetched/fetched/climateobs_readme.html').read()
t=re.sub(r'<[^>]+>',' ',t); t=html.unescape(t)
for m in re.finditer(r'https?://[^\s]+', t): print(m.group(0))
" | sort -u | head -40"}

